contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Drive C and assert the distinguishing property between msg.sender vs tx.origin check
    // params: description string, and an address that we will use to compare against jojoTeam
    function run(string calldata description, address expectedTeam) external {
        // read the public jojoTeam value
        address team = c.jojoTeam();

        // The behaviour difference: original modifier checks msg.sender, so when this contract
        // calls newEmergencyOracle, msg.sender == address(this) and the call succeeds only if
        // team == address(this). The mutant uses tx.origin so the call would instead succeed if
        // tx.origin == team (i.e. the externally-owned caller), which can differ.
        // We assert that calling newEmergencyOracle from this contract is allowed iff team == address(this).

        bool didRevert = false;
        // attempt the state-changing call; capture revert by try/catch
        try c.newEmergencyOracle(description) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // The rule: the call reverts exactly when jojoTeam is not this contract's address.
        // This holds under the original (msg.sender) but is broken by the mutant using tx.origin.
        assert(didRevert == (team != address(this)));
    }

    // allow receiving ETH if needed by test harness
    receive() external payable {}
    fallback() external payable {}
}

