contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    // Drive minimal sequence: call newEmergencyOracle from an arbitrary caller (this contract)
    // We take description as input. The property: when this contract is NOT jojoTeam, calling
    // newEmergencyOracle should revert; only jojoTeam may succeed. We express that by
    // requiring that if the call does not revert then the caller must be jojoTeam.

    function runTest(string calldata description, address jojoTeamAddress) external {
        // Precondition: the provided jojoTeamAddress equals c.jojoTeam() so the test ties the parameter
        // to the contract's configured jojoTeam. This is required so the property compares observable values.
        require(jojoTeamAddress == c.jojoTeam(), "precondition: mismatched jojoTeam param");

        // Attempt to call newEmergencyOracle from this contract and record whether it reverts.
        bool didRevert;
        // low-level call to observe revert boolean without propagating
        (bool ok, ) = address(c).call(abi.encodeWithSignature("newEmergencyOracle(string)", description));
        didRevert = !ok;

        // Assert the distinguishing rule: if the call succeeded then the caller must be jojoTeam.
        // On the original contract P this holds because only jojoTeam is allowed; on mutant M the
        // inverted require allows everyone except jojoTeam, so this assertion can be violated
        // (a non-jojo caller—this contract—would succeed and not equal jojoTeam).
        assert(didRevert || address(this) == jojoTeamAddress);
    }

    // Allow receiving ETH if needed by environment (not used but kept minimal as permitted)
    receive() external payable {}
}

