pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IEmergencyOracle {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;
    address jojoTeam = address(0xABCD);

    function setUp() public { c = new C(); }

    // Fuzzed: description bytes (as string) to let fuzzer vary calldata; at least one param required
    function testFuzz_property(string calldata description) public {
        // keep description within reasonable size
        bytes memory d = bytes(description);
        vm.assume(d.length <= 200);

        // make the jojoTeam caller be the tx sender
        vm.prank(jojoTeam);
        // call newEmergencyOracle and capture the emitted event by reading logs is complex; instead
        // we rely on the returned public visible oracle instance via emitted event isn't available,
        // but the created EmergencyOracle's owner is observable by scanning the chain: however the
        // contract C emits NewEmergencyOracle with (msg.sender, newOracle). We cannot read events from solidity tests,
        // so instead we can recreate the expected oracle address: the reference constructs the EmergencyOracle with owner = msg.sender (jojoTeam), while mutant uses address(this).
        // The created EmergencyOracle's constructor sets owner to the first ctor arg and exposes it via owner().
        // To observe the created oracle, we need the address. The only way to get it is to read the NewEmergencyOracle event, which isn't possible directly from solidity tests.
        // However, NewEmergencyOracle stores newOracle address; but we can reconstruct it because CREATE with deterministic nonce: when a contract creates another contract via new, the created address is based on creator nonce. The C contract's nonce increments each create; since setUp freshly deployed C and it hasn't created any contracts yet, the first created address is predictable as address = address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xd6), bytes1(0x94), address(c), uint8(1))))));
        // But relying on RLP/nonce encoding is brittle; instead we can call newEmergencyOracle and then brute-force scan plausible addresses around deployer's nonce 1 by probing owner() and finding the one whose owner equals jojoTeam. The mutant will instead return owner == address(c) for that deployed oracle, causing the assertion to fail for some inputs.

        // Call to create oracle
        vm.prank(jojoTeam);
        c.newEmergencyOracle(description);

        // Now search first few plausible contract addresses created by c (nonces 1..6)
        address found;
        for (uint256 n = 1; n <= 6; n++) {
            // compute CREATE address: keccak256(0xd6 0x94 <addr> <nonce>) per RLP for nonces < 128
            bytes memory data = abi.encodePacked(bytes1(0xd6), bytes1(0x94), address(c), uint8(n));
            address cand = address(uint160(uint256(keccak256(data))));
            // try staticcall to owner() to check if contract exists and matches expected interface
            try IEmergencyOracle(cand).owner() returns (address o) {
                // The reference contract sets owner to jojoTeam; the mutant sets owner to address(c)
                if (o == jojoTeam || o == address(c)) {
                    found = cand;
                    break;
                }
            } catch {
                // ignore non-contract addresses or non-matching
            }
        }

        // There must be at least one created contract in these nonces; require to keep test meaningful
        assertTrue(found != address(0));

        // Exactly one assertion: for the correct contract, the owner of the newly created EmergencyOracle equals the jojoTeam msg.sender for ANY description input.
        // The mutant that passes address(this) will cause owner() == address(c) for the created oracle for some inputs; the fuzzer will find such.
        assertTrue(IEmergencyOracle(found).owner() == jojoTeam);
    }
}

