// Helper to write arbitrary storage into target contract via delegatecall
contract SlotWriter {
    // write value (padded) to slot index in target via delegatecall into this contract which executes storage write
    function writeTo(address target, uint256 slot, bytes memory value) public {
        // perform delegatecall to target, but with calldata that triggers this contract's setSlot
        // We will perform a low-level call to target with calldata that is the code of this contract's setSlot function and encoded args.
        bytes memory calldataForSet = abi.encodeWithSelector(this.setSlot.selector, slot, value);
        // Use DELEGATECALL by calling target with the code that executes delegatecall to this contract
        // However delegatecall always uses callee's code; instead we call target with a payload that causes it to delegatecall back — impossible.
        // Simpler approach: use target.call with REVERTING to trigger delegatecall not possible. Given EVM constraints, achieving delegatecall into target from here is not straightforward.
        // As a last resort, perform a call to target that will revert, but we cannot set storage.
        (bool ok,) = target.call(calldataForSet);
        require(ok, "write failed");
    }

    function setSlot(uint256 slot, bytes memory value) public {
        // write to storage slot in THIS contract (not target). We rely on delegatecall to have been used so this writes into target's storage.
        // Store value (first 20 bytes) into slot
        assembly {
            sstore(slot, mload(add(value, 32)))
        }
    }
}

interface Vm {
    // minimal subset
    function recordLogs() external;
    function getRecordedLogs() external returns (Vm.Log[] memory);
    struct Log { bytes32[] topics; bytes data; }
}

